  "propositions": [
    {"id": "P1", "text": "A cultura popular deve receber apoio econômico e reconhecimento oficial através de auxílio financeiro a seus mestres e mestras."},
    {"id": "P2", "text": "A cultura popular e seus mestres estão marginalizados e invisibilizados pela mídia e pelos governos."},
    {"id": "P3", "text": "Os ritmos e saberes da cultura popular devem ser incluídos na economia e reconhecidos como patrimônio nacional com apoio aos artistas que os mantêm vivos."}
